  "ch1.read.rho": "Resistivity (mobility at 300 K)",
  "ch1.unit.ev": "{v} eV",
  "ch1.unit.rho": "{v} Ω·cm",
  "ch1.unit.T": "{k} K ({c} °C)",
  "ch1.unit.none": "undoped",
  "ch1.unit.N": "{v} /cm³",
  "ch1.cv.E": "Energy",
  "ch1.cv.Ec": "Conduction band bottom Ec",
  "ch1.cv.Ev": "Valence band top Ev",
  "ch1.cv.Ef": "Fermi level EF",
  "ch1.cv.f": "f(E)",
  "ch1.cv.T": "Temperature (K)",
  "ch1.cv.dens": "Density (/cm³)",
  "ch1.leg.n": "Electrons n",
